set-variable.value:
@{
            string s = (string)context.Variables["ai-cd"];
            int i = s.IndexOf("|");
            long t = 0;
            if (i > 0) { long.TryParse(s.Substring(0, i), out t); }
            return t;
        }

@{
            string s = (string)context.Variables["ai-cd"];
            int i = s.IndexOf("|");
            long t = 0;
            if (i >= 0) { long.TryParse(s.Substring(i + 1), out t); }
            return t;
        }

@{
            bool ok0 = (bool)context.Variables["ai-ok-0"];
            bool ok1 = (bool)context.Variables["ai-ok-1"];
            if (ok0 == ok1) { return ok0 ? (new Random().Next(2) == 0 ? "0" : "1") : "none"; }
            return ok0 ? "0" : "1";
        }

set-header.value:
@{
                            long soonest = Math.Min((long)context.Variables["ai-cd-0"], (long)context.Variables["ai-cd-1"]);
                            double secs = (soonest - DateTime.UtcNow.Ticks) / (double)TimeSpan.TicksPerSecond;
                            return Math.Max(1, (int)Math.Ceiling(secs)).ToString();
                        }

set-variable.value:
@{
                    double s = 30;
                    double v;
                    string ms = context.Response.Headers.GetValueOrDefault("retry-after-ms", context.Response.Headers.GetValueOrDefault("x-ms-retry-after-ms", ""));
                    string sec = context.Response.Headers.GetValueOrDefault("Retry-After", "");
                    if (double.TryParse(ms, out v)) { s = v / 1000; }
                    else if (double.TryParse(sec, out v)) { s = v; }
                    return (int)Math.Ceiling(Math.Min(Math.Max(s, 5), 300));
                }

@{
                    string s = (string)context.Variables["ai-cd-latest"];
                    int i = s.IndexOf("|");
                    long t = 0;
                    if (i > 0) { long.TryParse(s.Substring(0, i), out t); }
                    return t;
                }

@{
                    string s = (string)context.Variables["ai-cd-latest"];
                    int i = s.IndexOf("|");
                    long t = 0;
                    if (i >= 0) { long.TryParse(s.Substring(i + 1), out t); }
                    return t;
                }

@{
                    long proposed = DateTime.UtcNow.AddSeconds((int)context.Variables["ai-cd-secs"]).Ticks;
                    long existing = (string)context.Variables["ai-target"] == "0" ? (long)context.Variables["ai-latest-0"] : (long)context.Variables["ai-latest-1"];
                    return Math.Max(proposed, existing);
                }

cache-store-value.value:
@{
                    bool isZero = (string)context.Variables["ai-target"] == "0";
                    long u = (long)context.Variables["ai-new-until"];
                    long c0 = isZero ? u : (long)context.Variables["ai-latest-0"];
                    long c1 = isZero ? (long)context.Variables["ai-latest-1"] : u;
                    return c0.ToString() + "|" + c1.ToString();
                }

set-header.value:
@{
                        bool isZero = (string)context.Variables["ai-target"] == "0";
                        long now = DateTime.UtcNow.Ticks;
                        long otherUntil = isZero ? (long)context.Variables["ai-latest-1"] : (long)context.Variables["ai-latest-0"];
                        if (now >= otherUntil) { return "1"; }
                        long soonest = Math.Min(otherUntil, (long)context.Variables["ai-new-until"]);
                        int secs = (int)Math.Ceiling((soonest - now) / (double)TimeSpan.TicksPerSecond);
                        return Math.Max(1, secs).ToString();
                    }
